const LOGO='<img class="lg" src="data:image/webp;base64," alt="Grupo Lemos Passos" width="56" height="56">';

const seedTar=()=>[];
let D={users:[],sess:null,comps:[],rows:[],tar:seedTar(),exc:[]};
try{const s=localStorage.getItem('vf1');if(s)D=Object.assign(D,JSON.parse(s))}catch(e){}
const save=()=>{try{localStorage.setItem('vf1',JSON.stringify(D))}catch(e){toast('Não foi possível salvar neste navegador.')}};

let U={view:'dash',comp:null,auth:'in',nav:false,imp:{step:0},tab:'new',fd:{q:'',unid:'',mun:'',page:1,per:10,adv:false,uf:'',emp:'',banco:'',ag:'',conta:''},cf:{q:'',st:''},tf:{q:'',st:''},ef:{q:'',st:'',cat:''},modal:null,reveal:{}};

const toast=m=>{const t=$('#toast');t.textContent=m;t.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>t.style.display='none',3800)};
const ckey=c=>c.aa+'-'+String(c.mm).padStart(2,'0'),clab=c=>String(c.mm).padStart(2,'0')+'/'+c.aa;
const curComp=()=>D.comps.find(c=>c.id===U.comp)||[...D.comps].sort((a,b)=>ckey(b).localeCompare(ckey(a)))[0];

const vig=(t,k)=>t.ativa&&t.valor>0&&t.ini.slice(0,7)<=k&&(!t.fim||t.fim.slice(0,7)>=k);
const findTar=(unid,k)=>{const m=D.tar.filter(t=>vig(t,k)&&nrm(unid)&&nrm(t.unid)===nrm(unid));if(m.length===1)return m[0];const o=m.filter(t=>t.cat==='Ônibus');return o.length===1?o[0]:null};

function calc(r,k){const t=findTar(r.unid,k);const dias=Math.max(0,r.du-r.fer-r.falta),pas=dias*r.pass;
 r.dias=dias;r.passagens=pas;r.tarUsed=t?t.valor:null;r.vt=t?pas*t.valor:0;r.compl=t?Math.max(0,r.vt-r.pago):0;return r}

function genExc(r,comp){const o=[],n=(c,d)=>o.push({cat:c,desc:d});
 if(r.tarUsed==null)n('Tarifa ausente','Unidade "'+r.unid+'" sem tarifa ativa cadastrada para '+clab(comp)+'. Cadastre em Gestão de Tarifas.');
 else if(r.pago<r.vt)n('Valor complementar necessário','Pago '+fmt(r.pago)+' · calculado '+fmt(r.vt)+' · diferença '+fmt(r.vt-r.pago));
 else if(r.pago>r.vt)n('Valor pago divergente do calculado','Pago '+fmt(r.pago)+' acima do calculado '+fmt(r.vt));
 if(r.tarPlan!=null&&r.tarUsed!=null&&r.tarPlan!==r.tarUsed)n('Tarifa divergente da planilha','Planilha informa '+fmt(r.tarPlan)+'; cadastro da unidade '+fmt(r.tarUsed)+' (usada no cálculo)');return o}

function recalc(cid){const c=D.comps.find(x=>x.id===cid),k=ckey(c),old=D.exc.filter(e=>e.comp===cid);
 D.rows.filter(r=>r.comp===cid).forEach(r=>calc(r,k));
 const keep=old.filter(e=>!e.rowId),nw=[];
 D.rows.filter(r=>r.comp===cid).forEach(r=>genExc(r,c).forEach(x=>{const p=old.find(e=>e.rowId===r.id&&e.cat===x.cat);nw.push(p?{...p,desc:x.desc,nome:r.nome}:{id:uid(),comp:cid,rowId:r.id,nome:r.nome,date:new Date().toISOString().slice(0,10),status:'Pendente',hist:[],...x})}));
 D.exc=D.exc.filter(e=>e.comp!==cid).concat(keep,nw);c.upd=new Date().toISOString()}


const stats=cid=>{const R=D.rows.filter(r=>r.comp===cid),E=D.exc.filter(e=>e.comp===cid),s=(f)=>R.reduce((a,r)=>a+f(r),0);
 return{n:R.length,vt:s(r=>r.vt),pago:s(r=>r.pago),compl:s(r=>r.compl),ex:E.length,pend:E.filter(e=>e.status==='Pendente'||e.status==='Em análise').length,R,E}};


if(!D.v3){const SD=['alba','sedelemospassos','sotreq','pkgdobrasil'];D.tar=D.tar.filter(t=>!(SD.includes(nrm(t.unid))&&t.valor===590&&t.ini==='2026-01-01'&&!t.fim));D.ufs=D.ufs||[];[['AM','Amazonas'],['BA','Bahia'],['CE','Ceará'],['DF','Distrito Federal'],['ES','Espírito Santo'],['GO','Goiás'],['MG','Minas Gerais'],['MT','Mato Grosso'],['PA','Pará'],['PE','Pernambuco'],['SP','São Paulo']].forEach(([uf,nome])=>{if(!D.ufs.some(u=>u.uf===uf))D.ufs.push({uf,nome})});D.ufs.sort((a,b)=>a.uf.localeCompare(b.uf));D.v3=1;D.comps.filter(c=>c.status!=='Finalizada').forEach(c=>recalc(c.id));save()}

const HM={nome:['nome','funcionario','colaborador'],cpf:['cpf'],mat:['matricula','mat'],unid:['unidade','filial','lotacao'],comp:['competencia','mes','periodo'],du:['diasuteis','diasutil'],fer:['diasdeferias','ferias','diasferias'],falta:['diasdeatestadofalta','atestadofalta','faltas','diasdeatestado'],pass:['quantidadedepassagensdiarias','passagensdiarias','qtdpassagensdiarias','qtdpassagens','passagens'],pago:['valorpago','pago'],banco:['banco'],ag:['agencia'],conta:['conta'],uf:['uf','estado'],mun:['municipio','cidade'],emp:['empresa'],tar:['valortarifa','tarifa'],escala:['escala'],rs:['razaosocial'],cod:['codigolinha','codigo','linha']};
const REQ=['nome','cpf','mat','unid','comp','du','fer','falta','pass','pago'];
const LBL={nome:'Nome',cpf:'CPF',mat:'Matrícula',unid:'Unidade',comp:'Competência',du:'Dias Úteis',fer:'Dias de Férias',falta:'Dias de Atestado/Falta',pass:'Qtd. Passagens Diárias',pago:'Valor Pago'};

function pMoney(v){if(v===''||v==null)return NaN;if(typeof v==='number')return Math.round(v*100);let s=String(v).replace(/[R$\s]/g,'');if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');const n=Number(s);return isNaN(n)?NaN:Math.round(n*100)}
function pComp(v){if(typeof v==='number'&&v>20000){const d=new Date(Math.round((v-25569)*864e5));return String(d.getUTCMonth()+1).padStart(2,'0')+'/'+d.getUTCFullYear()}
 const s=String(v).trim();let m=s.match(/^(\d{1,2})\D+(\d{4})/);if(m)return m[1].padStart(2,'0')+'/'+m[2];m=s.match(/^(\d{4})\D+(\d{1,2})/);return m?m[2].padStart(2,'0')+'/'+m[1]:''}
function pCpf(v){let s=typeof v==='number'?String(Math.trunc(v)):String(v??'');s=s.replace(/\D/g,'');return s&&s.length<=11?s.padStart(11,'0'):s}
function cpfOk(c){if(!/^\d{11}$/.test(c)||/^(\d)\1+$/.test(c))return false;for(const n of[9,10]){let s=0;for(let i=0;i<n;i++)s+=+c[i]*(n+1-i);if((s*10%11)%10!==+c[n])return false}return true}
const pInt=v=>v===''||v==null?NaN:Number(String(v).replace(',','.'));

function parseRows(json){if(!json.length)return{err:'A planilha está vazia.'};const cols={};Object.keys(json[0]).forEach(h=>{for(const k in HM)if(!cols[k]&&HM[k].includes(nrm(h)))cols[k]=h});
 const miss=REQ.filter(k=>!cols[k]);if(miss.length)return{err:'Colunas obrigatórias ausentes: '+miss.map(k=>LBL[k]).join(', ')+'.'};
 const rows=json.map((j,i)=>{const g=k=>cols[k]?j[cols[k]]:'';const r={ln:i+2,nome:String(g('nome')).trim(),cpf:pCpf(g('cpf')),mat:String(g('mat')).trim(),unid:String(g('unid')).trim(),compS:pComp(g('comp')),du:pInt(g('du')),fer:g('fer')===''?0:pInt(g('fer')),falta:g('falta')===''?0:pInt(g('falta')),pass:pInt(g('pass')),pago:pMoney(g('pago')),
  uf:String(g('uf')).trim(),mun:String(g('mun')).trim(),emp:String(g('emp')).trim(),banco:String(g('banco')).trim(),ag:String(g('ag')).trim(),conta:String(g('conta')).trim()};const t=pMoney(g('tar'));if(!isNaN(t))r.tarVal=t;return r});return{rows}}

function validate(rows){const target=(()=>{const m={};rows.forEach(r=>m[r.compS]=(m[r.compS]||0)+1);return Object.entries(m).sort((a,b)=>b[1]-a[1])[0][0]})();
 const [mm,aa]=target.split('/'),tc=D.comps.find(c=>c.mm==+mm&&c.aa==+aa),seen={};
 rows.forEach(r=>{r.errs=[];r.warns=[];const e=m=>r.errs.push(m);
  if(!r.nome||!r.mat||!r.unid)e('Dados obrigatórios ausentes (nome, matrícula ou unidade)');
  if(!r.compS)e('Competência ausente ou em formato inválido');else if(r.compS!==target)e('Competência divergente ('+r.compS+' ≠ '+target+')');
  if(!cpfOk(r.cpf))e('CPF inválido');
  [['du',r.du],['fer',r.fer],['falta',r.falta],['pass',r.pass]].forEach(([k,v])=>{if(isNaN(v)||v<0)e('Valor inválido em '+LBL[k])});
  if(isNaN(r.pago)||r.pago<0)e('Valor pago inválido ou negativo');
  if(r.du>31)e('Dias úteis incompatível com a competência (máx. 31)');else if(r.fer+r.falta>r.du)e('Férias + faltas excedem os dias úteis');
  const key=r.compS+'|'+r.mat;if(r.mat){if(seen[key])e('Matrícula duplicada na competência (linha '+seen[key]+')');else seen[key]=r.ln}
  if(tc&&D.rows.some(x=>x.comp===tc.id&&x.mat===r.mat))e('Matrícula já importada nesta competência');
  if(!r.errs.length){const k=aa+'-'+mm.padStart(2,'0');calc(r,k);if(r.tarUsed==null)r.warns.push('Tarifa ausente');else if(r.pago!==r.vt)r.warns.push('Valor pago diverge do calculado')}});
 return{target,tc}}

const badge=s=>`<span class="pill ${{'Finalizada':'s-ok','Em conferência':'s-wa','Em processamento':'s-bl','Pendente':'s-wa','Em análise':'s-bl','Corrigida':'s-ok','Ignorada':'','Ativa':'s-ok','Inativa':''}[s]||''}">${s}</span>`;
