const NAV=[['dash','Dashboard'],['comp','Competências'],['imp','Importação de Dados'],['tar','Gestão de Tarifas'],['exc','Gestão de Exceções']];

const mask=c=>'***.'+c.slice(3,6)+'.'+c.slice(6,9)+'-**';
const cpfCell=(c,id)=>{const s=U.revAll||U.reveal[id];return (s?c:mask(c))+' <button class="eye" data-act="rev" data-id="'+id+'" aria-label="'+(s?'Ocultar':'Revelar')+' CPF" title="'+(s?'Ocultar':'Revelar')+' CPF">'+ic(s?'eyeoff':'eye')+'</button>'};
const cpfHead=()=>'CPF <button class="eye" data-act="reva" aria-label="Mostrar ou ocultar todos os CPFs" title="Mostrar/ocultar todos">'+ic(U.revAll?'eyeoff':'eye')+'</button>';
const pm=v=>{const n=parseFloat(String(v??'').replace(',','.'));return isNaN(n)?null:Math.round(n*100)};

